pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.deal(address(0x1), 1 ether);
        vm.prank(address(0x1));
        c.seedMarket{value: 0} (1000);

        vm.prank(address(0x2));
        c.getFreeKilo();
        vm.warp(block.timestamp + 86400);

        address bob = address(0x3);
        vm.prank(address(0x2));
        c.collectDrugs(bob);

        uint256 bobClaimed = c.claimedDrugs(bob);
        assertTrue(bobClaimed == 5184000, "Bob should have 5,184,000 claimedDrugs in correct contract");
    }
}
